record.field:
if record.type == 'opportunity' and record.stage_id.name == 'Agreement Executed':
    existing = env['project.project'].search([('opportunity_id', '=', record.id)], limit=1)
    if not existing:
        env['project.project'].create({
            'name': '[Partnership] ' + (record.name or 'New Partnership'),
            'partner_id': record.partner_id.id,
            'user_id': record.user_id.id,
            'opportunity_id': record.id,
        })
